mapper.select:
select t1.id, t1.code, t1.value, t1.value_type, t1.business_type, t1.belong, t1.description, t1.value_range, t1.name from bp_business_parameter t1 where t1.is_deleted = 0 and t1.is_display = 1
and t1.name like concat('%',#{name},'%')
and t1.code like concat('%',#{code},'%')
and t1.value_type = #{valueType}
and t1.business_type = #{businessType}
and t1.belong = #{belong}
order by t1.sort asc
